//! Go `strings`/`strconv`/`regexp` text semantics the SymDraw parser relies on.
//!
//! Unicode facts come from tables generated by the Go oracle toolchain
//! (`go_unicode.rs`), never from Rust's own (differently versioned) tables.

use super::go_unicode::{GO_PRINT, GO_SPACE, GO_TO_LOWER};

fn in_ranges(ranges: &[(u32, u32)], c: char) -> bool {
    let c = c as u32;
    ranges
        .binary_search_by(|&(lo, hi)| {
            if c < lo {
                std::cmp::Ordering::Greater
            } else if c > hi {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

/// Go `unicode.IsSpace`.
pub(crate) fn is_space(c: char) -> bool {
    in_ranges(GO_SPACE, c)
}

/// Go `strconv.IsPrint`.
fn is_print(c: char) -> bool {
    in_ranges(GO_PRINT, c)
}

/// Go `unicode.ToLower` for one rune.
pub(crate) fn to_lower_char(c: char) -> char {
    GO_TO_LOWER
        .binary_search_by_key(&(c as u32), |&(from, _)| from)
        .ok()
        .and_then(|i| char::from_u32(GO_TO_LOWER[i].1))
        .unwrap_or(c)
}

/// Go `strings.ToLower`.
pub(crate) fn to_lower(s: &str) -> String {
    s.chars().map(to_lower_char).collect()
}

/// Go `strings.TrimSpace`.
pub(crate) fn trim_space(s: &str) -> &str {
    s.trim_matches(is_space)
}

/// Go `strings.Fields`.
pub(crate) fn fields(s: &str) -> Vec<&str> {
    s.split(is_space).filter(|part| !part.is_empty()).collect()
}

/// Go `strings.Trim(s, "\"'")`.
pub(crate) fn trim_quotes(s: &str) -> &str {
    s.trim_matches(['"', '\''])
}

/// Go `strings.EqualFold(s, "end")` for an ASCII target without simple-fold
/// orbit partners outside ASCII.
pub(crate) fn equal_fold_ascii(s: &str, target: &str) -> bool {
    s.len() == target.len()
        && s.bytes()
            .zip(target.bytes())
            .all(|(a, b)| a.eq_ignore_ascii_case(&b))
}

/// Go `strconv.Quote` (the `%q` verb for strings).
pub(crate) fn quote(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        quote_rune(&mut out, c, '"');
    }
    out.push('"');
    out
}

/// Go `quoteChar` from encoding/json: `c` is a scanner byte, interpreted as a
/// Latin-1 code point (`string(rune(c))`).
pub(crate) fn quote_json_byte(byte: u8) -> String {
    if byte == b'\'' {
        return "'\\''".to_owned();
    }
    if byte == b'"' {
        return "'\"'".to_owned();
    }
    let quoted = quote(&char::from(byte).to_string());
    format!("'{}'", &quoted[1..quoted.len() - 1])
}

fn quote_rune(out: &mut String, c: char, quote: char) {
    if c == quote || c == '\\' {
        out.push('\\');
        out.push(c);
        return;
    }
    if c.is_ascii() {
        if (' '..='~').contains(&c) {
            out.push(c);
            return;
        }
    } else if is_print(c) {
        out.push(c);
        return;
    }
    match c {
        '\u{7}' => out.push_str("\\a"),
        '\u{8}' => out.push_str("\\b"),
        '\u{c}' => out.push_str("\\f"),
        '\n' => out.push_str("\\n"),
        '\r' => out.push_str("\\r"),
        '\t' => out.push_str("\\t"),
        '\u{b}' => out.push_str("\\v"),
        c if (c as u32) < 0x20 || c as u32 == 0x7f => {
            out.push_str(&format!("\\x{:02x}", c as u32));
        }
        c if (c as u32) < 0x10000 => out.push_str(&format!("\\u{:04x}", c as u32)),
        c => out.push_str(&format!("\\U{:08x}", c as u32)),
    }
}

/// ASCII word character as used by RE2's `\b`.
fn is_ascii_word(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

/// Simple case folding for the letters used by the `(?i)` Go patterns: the
/// only non-ASCII members of their orbits are U+212A (K) and U+017F (s).
fn fold(c: char) -> char {
    match c {
        '\u{212A}' => 'k',
        '\u{17F}' => 's',
        c => c.to_ascii_lowercase(),
    }
}

/// Matches `literal` case-insensitively at the start of `s`; returns the byte
/// length consumed.
fn match_ci(s: &str, literal: &str) -> Option<usize> {
    let mut consumed = 0;
    let mut chars = s.chars();
    for expected in literal.chars() {
        let c = chars.next()?;
        if fold(c) != expected {
            return None;
        }
        consumed += c.len_utf8();
    }
    Some(consumed)
}

/// RE2 `\b` (ASCII word boundary) at byte offset `at` of `s`.
fn boundary(s: &str, at: usize) -> bool {
    let before = s[..at].chars().next_back().is_some_and(is_ascii_word);
    let after = s[at..].chars().next().is_some_and(is_ascii_word);
    before != after
}

/// `FindString` for `(?i)^(a|b(-opt)?|...)\b` with leftmost-first alternation:
/// returns the matched text of the first alternative that completes.
pub(crate) fn find_ci_alternation<'a>(
    s: &'a str,
    alternatives: &[(&str, Option<&str>)],
) -> Option<&'a str> {
    for (base, optional) in alternatives {
        let Some(n) = match_ci(s, base) else { continue };
        if let Some(optional) = optional
            && let Some(m) = match_ci(&s[n..], optional)
            && boundary(s, n + m)
        {
            return Some(&s[..n + m]);
        }
        if boundary(s, n) {
            return Some(&s[..n]);
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn go_quote_matches_strconv() {
        assert_eq!(
            quote("a\"b\\c\n\t\u{7f}\u{85}é日\u{ad}\u{1F600}"),
            "\"a\\\"b\\\\c\\n\\t\\x7f\\u0085é日\\u00ad😀\""
        );
        assert_eq!(quote_json_byte(0xEF), "'ï'");
        assert_eq!(quote_json_byte(b'\n'), "'\\n'");
        assert_eq!(quote_json_byte(b'\''), "'\\''");
        assert_eq!(quote_json_byte(b'"'), "'\"'");
    }

    #[test]
    fn go_lower_and_space() {
        assert_eq!(to_lower("İΑΣ"), "iας".replace('ς', "σ"));
        assert!(is_space('\u{85}') && is_space('\u{a0}') && !is_space('\u{200b}'));
        assert_eq!(trim_space("\u{a0} x \u{3000}"), "x");
        assert_eq!(fields("a\u{a0}b  c"), ["a", "b", "c"]);
    }

    #[test]
    fn regexp_alternation_semantics() {
        let alts: &[(&str, Option<&str>)] = &[("class", Some("-v2")), ("state", None)];
        assert_eq!(find_ci_alternation("CLASS-V2 x", alts), Some("CLASS-V2"));
        assert_eq!(find_ci_alternation("class-v2x", alts), Some("class"));
        assert_eq!(find_ci_alternation("classes", alts), None);
        assert_eq!(
            find_ci_alternation("\u{17F}tate", alts),
            Some("\u{17F}tate")
        );
    }
}
